1	package com.bumptech.glide.load.resource.bitmap;
2	
3	import android.content.Context;
4	import android.graphics.Bitmap;
5	import androidx.annotation.NonNull;
6	import com.bumptech.glide.Glide;
7	import com.bumptech.glide.load.Transformation;
8	import com.bumptech.glide.load.engine.Resource;
9	import com.bumptech.glide.load.engine.bitmap_recycle.BitmapPool;
10	import com.bumptech.glide.request.target.Target;
11	import com.bumptech.glide.util.Util;
12	import java.nio.charset.Charset;
13	import java.security.MessageDigest;
14	
15	/**
16	 * A simple {@link com.bumptech.glide.load.Transformation} for transforming {@link
17	 * android.graphics.Bitmap}s that abstracts away dealing with {@link
18	 * com.bumptech.glide.load.engine.Resource} objects for subclasses.
19	 *
20	 * <p>Use cases will look something like this:
21	 *
22	 * <pre>{@code
23	 * public class FillSpace extends BitmapTransformation {
24	 *     private static final String ID = "com.bumptech.glide.transformations.FillSpace";
25	 *     private static final byte[] ID_BYTES = ID.getBytes(Charset.forName("UTF-8"));
26	 *
27	 *     {@literal @Override}
28	 *     public Bitmap transform(BitmapPool pool, Bitmap toTransform, int outWidth, int outHeight) {
29	 *         if (toTransform.getWidth() == outWidth && toTransform.getHeight() == outHeight) {
30	 *             return toTransform;
31	 *         }
32	 *
33	 *         return Bitmap.createScaledBitmap(toTransform, outWidth, outHeight, true);
34	 *     }
35	 *
36	 *     {@literal @Override}
37	 *     public boolean equals(Object o) {
38	 *       return o instanceof FillSpace;
39	 *     }
40	 *
41	 *     {@literal @Override}
42	 *     public int hashCode() {
43	 *       return ID.hashCode();
44	 *     }
45	 *
46	 *     {@literal @Override}
47	 *     public void updateDiskCacheKey(MessageDigest messageDigest) {
48	 *       messageDigest.update(ID_BYTES);
49	 *     }
50	 * }
51	 * }</pre>
52	 *
53	 * <p>Using the fully qualified class name as a static final {@link String} (not {@link
54	 * Class#getName()} to avoid proguard obfuscation) is an easy way to implement {@link
55	 * #updateDiskCacheKey(java.security.MessageDigest)}} correctly. If additional arguments are
56	 * required they can be passed in to the constructor of the {@code Transformation} and then used to
57	 * update the {@link java.security.MessageDigest} passed in to {@link
58	 * #updateDiskCacheKey(MessageDigest)}. If arguments are primitive types, they can typically easily
59	 * be serialized using {@link java.nio.ByteBuffer}. {@link String} types can be serialized with
60	 * {@link String#getBytes(Charset)} using the constant {@link #CHARSET}.
61	 *
62	 * <p>As with all {@link Transformation}s, all subclasses <em>must</em> implement {@link
63	 * #equals(Object)} and {@link #hashCode()} for memory caching to work correctly.
64	 */
65	public abstract class BitmapTransformation implements Transformation<Bitmap> {
66	
67	  @NonNull
68	  @Override
69	  public final Resource<Bitmap> transform(
70	      @NonNull Context context, @NonNull Resource<Bitmap> resource, int outWidth, int outHeight) {
71	    if (!Util.isValidDimensions(outWidth, outHeight)) {
72	      throw new IllegalArgumentException(
73	          "Cannot apply transformation on width: "
74	              + outWidth
75	              + " or height: "
76	              + outHeight
77	              + " less than or equal to zero and not Target.SIZE_ORIGINAL");
78	    }
79	    BitmapPool bitmapPool = Glide.get(context).getBitmapPool();
80	    Bitmap toTransform = resource.get();
81	    int targetWidth = outWidth == Target.SIZE_ORIGINAL ? toTransform.getWidth() : outWidth;
82	    int targetHeight = outHeight == Target.SIZE_ORIGINAL ? toTransform.getHeight() : outHeight;
83	    Bitmap transformed = transform(bitmapPool, toTransform, targetWidth, targetHeight);
84	
85	    final Resource<Bitmap> result;
86	    if (toTransform.equals(transformed)) {
87	      result = resource;
88	    } else {
89	      result = BitmapResource.obtain(transformed, bitmapPool);
90	    }
91	    return result;
92	  }
93	
94	  /**
95	   * Transforms the given {@link android.graphics.Bitmap} based on the given dimensions and returns
96	   * the transformed result.
97	   *
98	   * <p>The provided Bitmap, toTransform, should not be recycled or returned to the pool. Glide will
99	   * automatically recycle and/or reuse toTransform if the transformation returns a different
100	   * Bitmap. Similarly implementations should never recycle or return Bitmaps that are returned as
101	   * the result of this method. Recycling or returning the provided and/or the returned Bitmap to
102	   * the pool will lead to a variety of runtime exceptions and drawing errors. See #408 for an
103	   * example. If the implementation obtains and discards intermediate Bitmaps, they may safely be
104	   * returned to the BitmapPool and/or recycled.
105	   *
106	   * <p>outWidth and outHeight will never be {@link
107	   * com.bumptech.glide.request.target.Target#SIZE_ORIGINAL}, this class converts them to be the
108	   * size of the Bitmap we're going to transform before calling this method.
109	   *
110	   * @param pool A {@link com.bumptech.glide.load.engine.bitmap_recycle.BitmapPool} that can be used
111	   *     to obtain and return intermediate {@link Bitmap}s used in this transformation. For every
112	   *     {@link android.graphics.Bitmap} obtained from the pool during this transformation, a {@link
113	   *     android.graphics.Bitmap} must also be returned.
114	   * @param toTransform The {@link android.graphics.Bitmap} to transform.
115	   * @param outWidth The ideal width of the transformed bitmap (the transformed width does not need
116	   *     to match exactly).
117	   * @param outHeight The ideal height of the transformed bitmap (the transformed height does not
118	   *     need to match exactly).
119	   */
120	  protected abstract Bitmap transform(
121	      @NonNull BitmapPool pool, @NonNull Bitmap toTransform, int outWidth, int outHeight);
122	}
