7	
8	/**
9	 * Scale the image so that either the width of the image matches the given width and the height of
10	 * the image is greater than the given height or vice versa, and then crop the larger dimension to
11	 * match the given dimension.
12	 *
13	 * <p>Does not maintain the image's aspect ratio
14	 */
15	public class CenterCrop extends BitmapTransformation {
16	  private static final String ID = "com.bumptech.glide.load.resource.bitmap.CenterCrop";
17	  private static final byte[] ID_BYTES = ID.getBytes(CHARSET);
18	
19	  @Override
20	  protected Bitmap transform(
21	      @NonNull BitmapPool pool, @NonNull Bitmap toTransform, int outWidth, int outHeight) {
22	    return TransformationUtils.centerCrop(pool, toTransform, outWidth, outHeight);
23	  }
24	
25	  @Override
26	  public boolean equals(Object o) {
27	    return o instanceof CenterCrop;
28	  }
29	
30	  @Override
31	  public int hashCode() {
32	    return ID.hashCode();
33	  }
34	
35	  @Override
36	  public void updateDiskCacheKey(@NonNull MessageDigest messageDigest) {
37	    messageDigest.update(ID_BYTES);
38	  }
39	}
