1	package com.bumptech.glide.signature;
2	
3	import androidx.annotation.NonNull;
4	import com.bumptech.glide.load.Key;
5	import com.bumptech.glide.util.Preconditions;
6	import java.security.MessageDigest;
7	
8	/**
9	 * Wraps an {@link java.lang.Object}, delegating {@link #equals(Object)} and {@link #hashCode()} to
10	 * the wrapped Object and providing the bytes of the result of the Object's {@link #toString()}
11	 * method to the {@link java.security.MessageDigest} in {@link
12	 * #updateDiskCacheKey(java.security.MessageDigest)}.
13	 *
14	 * <p>The Object's {@link #toString()} method must be unique and suitable for use as a disk cache
15	 * key.
16	 */
17	public final class ObjectKey implements Key {
18	  private final Object object;
19	
20	  public ObjectKey(@NonNull Object object) {
21	    this.object = Preconditions.checkNotNull(object);
22	  }
23	
24	  @Override
25	  public String toString() {
26	    return "ObjectKey{" + "object=" + object + '}';
27	  }
28	
29	  @Override
30	  public boolean equals(Object o) {
31	    if (o instanceof ObjectKey) {
32	      ObjectKey other = (ObjectKey) o;
33	      return object.equals(other.object);
34	    }
35	    return false;
36	  }
37	
38	  @Override
39	  public int hashCode() {
40	    return object.hashCode();
41	  }
42	
43	  @Override
44	  public void updateDiskCacheKey(@NonNull MessageDigest messageDigest) {
45	    messageDigest.update(object.toString().getBytes(CHARSET));
46	  }
47	}
