10	
11	  private Preconditions() {
12	    // Utility class.
13	  }
14	
15	  public static void checkArgument(boolean expression) {
16	    checkArgument(expression, /* message= */ "");
17	  }
18	
19	  public static void checkArgument(boolean expression, @NonNull String message) {
20	    if (!expression) {
21	      throw new IllegalArgumentException(message);
22	    }
23	  }
24	
25	  @NonNull
26	  public static <T> T checkNotNull(@Nullable T arg) {
27	    return checkNotNull(arg, "Argument must not be null");
28	  }
29	
30	  @NonNull
31	  public static <T> T checkNotNull(@Nullable T arg, @NonNull String message) {
32	    if (arg == null) {
33	      throw new NullPointerException(message);
34	    }
35	    return arg;
36	  }
37	
38	  @NonNull
39	  public static String checkNotEmpty(@Nullable String string) {
40	    if (TextUtils.isEmpty(string)) {
41	      throw new IllegalArgumentException("Must not be null or empty");
42	    }
43	    return string;
44	  }
45	
46	  @NonNull
