1	package com.bumptech.glide.util;
2	
3	import android.annotation.TargetApi;
4	import android.os.Build;
5	import android.os.SystemClock;
6	
7	/** A class for logging elapsed real time in millis. */
8	public final class LogTime {
9	  private static final double MILLIS_MULTIPLIER =
10	      Build.VERSION.SDK_INT >= Build.VERSION_CODES.JELLY_BEAN_MR1 ? 1d / Math.pow(10, 6) : 1d;
11	
12	  private LogTime() {
13	    // Utility class.
14	  }
15	
16	  /**
17	   * Returns the current time in either millis or nanos depending on the api level to be used with
18	   * {@link #getElapsedMillis(long)}.
19	   */
20	  @TargetApi(Build.VERSION_CODES.JELLY_BEAN_MR1)
21	  public static long getLogTime() {
22	    if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.JELLY_BEAN_MR1) {
23	      return SystemClock.elapsedRealtimeNanos();
24	    } else {
25	      return SystemClock.uptimeMillis();
26	    }
27	  }
28	
29	  /**
30	   * Returns the time elapsed since the given logTime in millis.
31	   *
32	   * @param logTime The start time of the event.
33	   */
34	  public static double getElapsedMillis(long logTime) {
35	    return (getLogTime() - logTime) * MILLIS_MULTIPLIER;
36	  }
37	}
