8	import com.bumptech.glide.util.LruCache;
9	
10	/** An LRU in memory cache for {@link com.bumptech.glide.load.engine.Resource}s. */
11	public class LruResourceCache extends LruCache<Key, Resource<?>> implements MemoryCache {
12	  private ResourceRemovedListener listener;
13	
14	  /**
15	   * Constructor for LruResourceCache.
16	   *
17	   * @param size The maximum size in bytes the in memory cache can use.
18	   */
19	  public LruResourceCache(long size) {
20	    super(size);
21	  }
22	
23	  @Override
24	  public void setResourceRemovedListener(@NonNull ResourceRemovedListener listener) {
25	    this.listener = listener;
26	  }
27	
28	  @Override
29	  protected void onItemEvicted(@NonNull Key key, @Nullable Resource<?> item) {
30	    if (listener != null && item != null) {
31	      listener.onResourceRemoved(item);
32	    }
33	  }
34	
35	  @Override
36	  protected int getSize(@Nullable Resource<?> item) {
37	    if (item == null) {
38	      return super.getSize(null);
39	    } else {
40	      return item.getSize();
41	    }
42	  }
43	
44	  @SuppressLint("InlinedApi")
45	  @Override
46	  public void trimMemory(int level) {
47	    if (level >= android.content.ComponentCallbacks2.TRIM_MEMORY_BACKGROUND) {
48	      // Entering list of cached background apps
49	      // Evict our entire bitmap cache
50	      clearMemory();
51	    } else if (level >= android.content.ComponentCallbacks2.TRIM_MEMORY_UI_HIDDEN
52	        || level == android.content.ComponentCallbacks2.TRIM_MEMORY_RUNNING_CRITICAL) {
53	      // The app's UI is no longer visible, or app is in the foreground but system is running
54	      // critically low on memory
55	      // Evict oldest half of our bitmap cache
56	      trimToSize(getMaxSize() / 2);
57	    }
58	  }
