1	package com.bumptech.glide.load.engine.cache;
2	
3	import android.annotation.TargetApi;
4	import android.app.ActivityManager;
5	import android.content.Context;
6	import android.os.Build;
7	import android.text.format.Formatter;
8	import android.util.DisplayMetrics;
9	import android.util.Log;
10	import androidx.annotation.VisibleForTesting;
11	import com.bumptech.glide.util.Preconditions;
12	import com.bumptech.glide.util.Synthetic;
13	
14	/**
15	 * A calculator that tries to intelligently determine cache sizes for a given device based on some
16	 * constants and the devices screen density, width, and height.
17	 */
18	public final class MemorySizeCalculator {
19	  private static final String TAG = "MemorySizeCalculator";
20	  @VisibleForTesting static final int BYTES_PER_ARGB_8888_PIXEL = 4;
21	  private static final int LOW_MEMORY_BYTE_ARRAY_POOL_DIVISOR = 2;
22	
23	  private final int bitmapPoolSize;
24	  private final int memoryCacheSize;
25	  private final Context context;
26	  private final int arrayPoolSize;
27	
28	  interface ScreenDimensions {
29	    int getWidthPixels();
30	
31	    int getHeightPixels();
32	  }
33	
34	  // Package private to avoid PMD warning.
35	  MemorySizeCalculator(MemorySizeCalculator.Builder builder) {
36	    this.context = builder.context;
37	
38	    arrayPoolSize =
39	        isLowMemoryDevice(builder.activityManager)
40	            ? builder.arrayPoolSizeBytes / LOW_MEMORY_BYTE_ARRAY_POOL_DIVISOR
41	            : builder.arrayPoolSizeBytes;
42	    int maxSize =
43	        getMaxSize(
44	            builder.activityManager, builder.maxSizeMultiplier, builder.lowMemoryMaxSizeMultiplier);
45	
46	    int widthPixels = builder.screenDimensions.getWidthPixels();
47	    int heightPixels = builder.screenDimensions.getHeightPixels();
48	    int screenSize = widthPixels * heightPixels * BYTES_PER_ARGB_8888_PIXEL;
49	
50	    int targetBitmapPoolSize = Math.round(screenSize * builder.bitmapPoolScreens);
51	
52	    int targetMemoryCacheSize = Math.round(screenSize * builder.memoryCacheScreens);
53	    int availableSize = maxSize - arrayPoolSize;
54	
55	    if (targetMemoryCacheSize + targetBitmapPoolSize <= availableSize) {
56	      memoryCacheSize = targetMemoryCacheSize;
57	      bitmapPoolSize = targetBitmapPoolSize;
58	    } else {
59	      float part = availableSize / (builder.bitmapPoolScreens + builder.memoryCacheScreens);
60	      memoryCacheSize = Math.round(part * builder.memoryCacheScreens);
61	      bitmapPoolSize = Math.round(part * builder.bitmapPoolScreens);
62	    }
63	
64	    if (Log.isLoggable(TAG, Log.DEBUG)) {
65	      Log.d(
66	          TAG,
67	          "Calculation complete"
68	              + ", Calculated memory cache size: "
69	              + toMb(memoryCacheSize)
70	              + ", pool size: "
71	              + toMb(bitmapPoolSize)
72	              + ", byte array size: "
73	              + toMb(arrayPoolSize)
74	              + ", memory class limited? "
75	              + (targetMemoryCacheSize + targetBitmapPoolSize > maxSize)
76	              + ", max size: "
77	              + toMb(maxSize)
78	              + ", memoryClass: "
79	              + builder.activityManager.getMemoryClass()
80	              + ", isLowMemoryDevice: "
81	              + isLowMemoryDevice(builder.activityManager));
82	    }
83	  }
84	
85	  /** Returns the recommended memory cache size for the device it is run on in bytes. */
86	  public int getMemoryCacheSize() {
87	    return memoryCacheSize;
88	  }
89	
90	  /** Returns the recommended bitmap pool size for the device it is run on in bytes. */
91	  public int getBitmapPoolSize() {
92	    return bitmapPoolSize;
93	  }
94	
95	  /** Returns the recommended array pool size for the device it is run on in bytes. */
96	  public int getArrayPoolSizeInBytes() {
97	    return arrayPoolSize;
98	  }
99	
100	  private static int getMaxSize(
101	      ActivityManager activityManager, float maxSizeMultiplier, float lowMemoryMaxSizeMultiplier) {
102	    final int memoryClassBytes = activityManager.getMemoryClass() * 1024 * 1024;
103	    final boolean isLowMemoryDevice = isLowMemoryDevice(activityManager);
104	    return Math.round(
105	        memoryClassBytes * (isLowMemoryDevice ? lowMemoryMaxSizeMultiplier : maxSizeMultiplier));
106	  }
107	
108	  private String toMb(int bytes) {
109	    return Formatter.formatFileSize(context, bytes);
110	  }
111	
112	  @TargetApi(Build.VERSION_CODES.KITKAT)
113	  @Synthetic
114	  static boolean isLowMemoryDevice(ActivityManager activityManager) {
115	    // Explicitly check with an if statement, on some devices both parts of boolean expressions
116	    // can be evaluated even if we'd normally expect a short circuit.
117	    //noinspection SimplifiableIfStatement
118	    if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.KITKAT) {
119	      return activityManager.isLowRamDevice();
120	    } else {
121	      return true;
122	    }
123	  }
124	
125	  /**
126	   * Constructs an {@link MemorySizeCalculator} with reasonable defaults that can be optionally
127	   * overridden.
128	   */
129	  // Public API.
130	  @SuppressWarnings({"WeakerAccess", "unused"})
131	  public static final class Builder {
132	    @VisibleForTesting static final int MEMORY_CACHE_TARGET_SCREENS = 2;
133	
134	    /**
135	     * On Android O+, we use {@link android.graphics.Bitmap.Config#HARDWARE} for all reasonably
136	     * sized images unless we're creating thumbnails for the first time. As a result, the Bitmap
137	     * pool is much less important on O than it was on previous versions.
138	     */
139	    static final int BITMAP_POOL_TARGET_SCREENS =
140	        Build.VERSION.SDK_INT < Build.VERSION_CODES.O ? 4 : 1;
141	
142	    static final float MAX_SIZE_MULTIPLIER = 0.4f;
143	    static final float LOW_MEMORY_MAX_SIZE_MULTIPLIER = 0.33f;
144	    // 4MB.
145	    static final int ARRAY_POOL_SIZE_BYTES = 4 * 1024 * 1024;
146	
147	    @Synthetic final Context context;
148	
149	    // Modifiable (non-final) for testing.
150	    @Synthetic ActivityManager activityManager;
151	    @Synthetic ScreenDimensions screenDimensions;
152	
153	    @Synthetic float memoryCacheScreens = MEMORY_CACHE_TARGET_SCREENS;
154	    @Synthetic float bitmapPoolScreens = BITMAP_POOL_TARGET_SCREENS;
155	    @Synthetic float maxSizeMultiplier = MAX_SIZE_MULTIPLIER;
156	    @Synthetic float lowMemoryMaxSizeMultiplier = LOW_MEMORY_MAX_SIZE_MULTIPLIER;
157	    @Synthetic int arrayPoolSizeBytes = ARRAY_POOL_SIZE_BYTES;
158	
159	    public Builder(Context context) {
160	      this.context = context;
161	      activityManager = (ActivityManager) context.getSystemService(Context.ACTIVITY_SERVICE);
162	      screenDimensions =
163	          new DisplayMetricsScreenDimensions(context.getResources().getDisplayMetrics());
164	
165	      // On Android O+ Bitmaps are allocated natively, ART is much more efficient at managing
166	      // garbage and we rely heavily on HARDWARE Bitmaps, making Bitmap re-use much less important.
167	      // We prefer to preserve RAM on these devices and take the small performance hit of not
168	      // re-using Bitmaps and textures when loading very small images or generating thumbnails.
169	      if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O && isLowMemoryDevice(activityManager)) {
170	        bitmapPoolScreens = 0;
171	      }
172	    }
173	
174	    /**
175	     * Sets the number of device screens worth of pixels the {@link
176	     * com.bumptech.glide.load.engine.cache.MemoryCache} should be able to hold and returns this
177	     * Builder.
178	     */
179	    public Builder setMemoryCacheScreens(float memoryCacheScreens) {
180	      Preconditions.checkArgument(
181	          memoryCacheScreens >= 0, "Memory cache screens must be greater than or equal to 0");
182	      this.memoryCacheScreens = memoryCacheScreens;
183	      return this;
184	    }
185	
186	    /**
187	     * Sets the number of device screens worth of pixels the {@link
188	     * com.bumptech.glide.load.engine.bitmap_recycle.BitmapPool} should be able to hold and returns
189	     * this Builder.
190	     */
191	    public Builder setBitmapPoolScreens(float bitmapPoolScreens) {
192	      Preconditions.checkArgument(
193	          bitmapPoolScreens >= 0, "Bitmap pool screens must be greater than or equal to 0");
194	      this.bitmapPoolScreens = bitmapPoolScreens;
195	      return this;
196	    }
197	
198	    /**
199	     * Sets the maximum percentage of the device's memory class for standard devices that can be
200	     * taken up by Glide's {@link com.bumptech.glide.load.engine.cache.MemoryCache} and {@link
201	     * com.bumptech.glide.load.engine.bitmap_recycle.BitmapPool} put together, and returns this
202	     * builder.
203	     */
204	    public Builder setMaxSizeMultiplier(float maxSizeMultiplier) {
205	      Preconditions.checkArgument(
206	          maxSizeMultiplier >= 0 && maxSizeMultiplier <= 1,
207	          "Size multiplier must be between 0 and 1");
208	      this.maxSizeMultiplier = maxSizeMultiplier;
209	      return this;
210	    }
211	
212	    /**
213	     * Sets the maximum percentage of the device's memory class for low ram devices that can be
214	     * taken up by Glide's {@link com.bumptech.glide.load.engine.cache.MemoryCache} and {@link
215	     * com.bumptech.glide.load.engine.bitmap_recycle.BitmapPool} put together, and returns this
216	     * builder.
217	     *
218	     * @see ActivityManager#isLowRamDevice()
219	     */
220	    public Builder setLowMemoryMaxSizeMultiplier(float lowMemoryMaxSizeMultiplier) {
221	      Preconditions.checkArgument(
222	          lowMemoryMaxSizeMultiplier >= 0 && lowMemoryMaxSizeMultiplier <= 1,
223	          "Low memory max size multiplier must be between 0 and 1");
224	      this.lowMemoryMaxSizeMultiplier = lowMemoryMaxSizeMultiplier;
225	      return this;
226	    }
227	
228	    /**
229	     * Sets the size in bytes of the {@link com.bumptech.glide.load.engine.bitmap_recycle.ArrayPool}
230	     * to use to store temporary arrays while decoding data and returns this builder.
231	     *
232	     * <p>This number will be halved on low memory devices that return {@code true} from {@link
233	     * ActivityManager#isLowRamDevice()}.
234	     */
235	    public Builder setArrayPoolSize(int arrayPoolSizeBytes) {
236	      this.arrayPoolSizeBytes = arrayPoolSizeBytes;
237	      return this;
238	    }
239	
240	    @VisibleForTesting
241	    Builder setActivityManager(ActivityManager activityManager) {
242	      this.activityManager = activityManager;
243	      return this;
244	    }
245	
246	    @VisibleForTesting
247	    Builder setScreenDimensions(ScreenDimensions screenDimensions) {
248	      this.screenDimensions = screenDimensions;
249	      return this;
250	    }
251	
252	    public MemorySizeCalculator build() {
253	      return new MemorySizeCalculator(this);
254	    }
255	  }
256	
257	  private static final class DisplayMetricsScreenDimensions implements ScreenDimensions {
258	    private final DisplayMetrics displayMetrics;
259	
260	    DisplayMetricsScreenDimensions(DisplayMetrics displayMetrics) {
261	      this.displayMetrics = displayMetrics;
262	    }
263	
264	    @Override
265	    public int getWidthPixels() {
266	      return displayMetrics.widthPixels;
267	    }
268	
269	    @Override
270	    public int getHeightPixels() {
271	      return displayMetrics.heightPixels;
272	    }
273	  }
274	}
