1	package com.bumptech.glide.load.engine.bitmap_recycle;
2	
3	import android.annotation.SuppressLint;
4	import android.annotation.TargetApi;
5	import android.content.ComponentCallbacks2;
6	import android.graphics.Bitmap;
7	import android.graphics.Color;
8	import android.os.Build;
9	import android.util.Log;
10	import androidx.annotation.NonNull;
11	import androidx.annotation.Nullable;
12	import com.bumptech.glide.util.Synthetic;
13	import java.util.Arrays;
14	import java.util.Collections;
15	import java.util.HashSet;
16	import java.util.Set;
17	
18	/**
19	 * An {@link com.bumptech.glide.load.engine.bitmap_recycle.BitmapPool} implementation that uses an
20	 * {@link com.bumptech.glide.load.engine.bitmap_recycle.LruPoolStrategy} to bucket {@link Bitmap}s
21	 * and then uses an LRU eviction policy to evict {@link android.graphics.Bitmap}s from the least
22	 * recently used bucket in order to keep the pool below a given maximum size limit.
23	 */
24	public class LruBitmapPool implements BitmapPool {
25	  private static final String TAG = "LruBitmapPool";
26	  private static final Bitmap.Config DEFAULT_CONFIG = Bitmap.Config.ARGB_8888;
27	
28	  private final LruPoolStrategy strategy;
29	  private final Set<Bitmap.Config> allowedConfigs;
30	  private final long initialMaxSize;
31	  private final BitmapTracker tracker;
32	
33	  private long maxSize;
34	  private long currentSize;
35	  private int hits;
36	  private int misses;
37	  private int puts;
38	  private int evictions;
39	
40	  // Exposed for testing only.
41	  LruBitmapPool(long maxSize, LruPoolStrategy strategy, Set<Bitmap.Config> allowedConfigs) {
42	    this.initialMaxSize = maxSize;
43	    this.maxSize = maxSize;
44	    this.strategy = strategy;
45	    this.allowedConfigs = allowedConfigs;
46	    this.tracker = new NullBitmapTracker();
47	  }
48	
49	  /**
50	   * Constructor for LruBitmapPool.
51	   *
52	   * @param maxSize The initial maximum size of the pool in bytes.
53	   */
54	  public LruBitmapPool(long maxSize) {
55	    this(maxSize, getDefaultStrategy(), getDefaultAllowedConfigs());
56	  }
57	
58	  /**
59	   * Constructor for LruBitmapPool.
60	   *
61	   * @param maxSize The initial maximum size of the pool in bytes.
62	   * @param allowedConfigs A white listed put of {@link android.graphics.Bitmap.Config} that are
63	   *     allowed to be put into the pool. Configs not in the allowed put will be rejected.
64	   */
65	  // Public API.
66	  @SuppressWarnings("unused")
67	  public LruBitmapPool(long maxSize, Set<Bitmap.Config> allowedConfigs) {
68	    this(maxSize, getDefaultStrategy(), allowedConfigs);
69	  }
70	
71	  /** Returns the number of cache hits for bitmaps in the pool. */
72	  public long hitCount() {
73	    return hits;
74	  }
75	
76	  /** Returns the number of cache misses for bitmaps in the pool. */
77	  public long missCount() {
78	    return misses;
79	  }
80	
81	  /** Returns the number of bitmaps that have been evicted from the pool. */
82	  public long evictionCount() {
83	    return evictions;
84	  }
85	
86	  /** Returns the current size of the pool in bytes. */
87	  public long getCurrentSize() {
88	    return currentSize;
89	  }
90	
91	  @Override
92	  public long getMaxSize() {
93	    return maxSize;
94	  }
95	
96	  @Override
97	  public synchronized void setSizeMultiplier(float sizeMultiplier) {
98	    maxSize = Math.round(initialMaxSize * sizeMultiplier);
99	    evict();
100	  }
101	
102	  @Override
103	  public synchronized void put(Bitmap bitmap) {
104	    if (bitmap == null) {
105	      throw new NullPointerException("Bitmap must not be null");
106	    }
107	    if (bitmap.isRecycled()) {
108	      throw new IllegalStateException("Cannot pool recycled bitmap");
109	    }
110	    if (!bitmap.isMutable()
111	        || strategy.getSize(bitmap) > maxSize
112	        || !allowedConfigs.contains(bitmap.getConfig())) {
113	      if (Log.isLoggable(TAG, Log.VERBOSE)) {
114	        Log.v(
115	            TAG,
116	            "Reject bitmap from pool"
117	                + ", bitmap: "
118	                + strategy.logBitmap(bitmap)
119	                + ", is mutable: "
120	                + bitmap.isMutable()
121	                + ", is allowed config: "
122	                + allowedConfigs.contains(bitmap.getConfig()));
123	      }
124	      bitmap.recycle();
125	      return;
126	    }
127	
128	    final int size = strategy.getSize(bitmap);
129	    strategy.put(bitmap);
130	    tracker.add(bitmap);
131	
132	    puts++;
133	    currentSize += size;
134	
135	    if (Log.isLoggable(TAG, Log.VERBOSE)) {
136	      Log.v(TAG, "Put bitmap in pool=" + strategy.logBitmap(bitmap));
137	    }
138	    dump();
139	
140	    evict();
141	  }
142	
143	  private void evict() {
144	    trimToSize(maxSize);
145	  }
146	
147	  @Override
148	  @NonNull
149	  public Bitmap get(int width, int height, Bitmap.Config config) {
150	    Bitmap result = getDirtyOrNull(width, height, config);
151	    if (result != null) {
152	      // Bitmaps in the pool contain random data that in some cases must be cleared for an image
153	      // to be rendered correctly. we shouldn't force all consumers to independently erase the
154	      // contents individually, so we do so here. See issue #131.
155	      result.eraseColor(Color.TRANSPARENT);
156	    } else {
157	      result = createBitmap(width, height, config);
158	    }
159	
160	    return result;
161	  }
162	
163	  @NonNull
164	  @Override
165	  public Bitmap getDirty(int width, int height, Bitmap.Config config) {
166	    Bitmap result = getDirtyOrNull(width, height, config);
167	    if (result == null) {
168	      result = createBitmap(width, height, config);
169	    }
170	    return result;
171	  }
172	
173	  @NonNull
174	  private static Bitmap createBitmap(int width, int height, @Nullable Bitmap.Config config) {
175	    return Bitmap.createBitmap(width, height, config != null ? config : DEFAULT_CONFIG);
176	  }
177	
178	  @TargetApi(Build.VERSION_CODES.O)
179	  private static void assertNotHardwareConfig(Bitmap.Config config) {
180	    // Avoid short circuiting on sdk int since it breaks on some versions of Android.
181	    if (Build.VERSION.SDK_INT < Build.VERSION_CODES.O) {
182	      return;
183	    }
184	
185	    if (config == Bitmap.Config.HARDWARE) {
186	      throw new IllegalArgumentException(
187	          "Cannot create a mutable Bitmap with config: "
188	              + config
189	              + ". Consider setting Downsampler#ALLOW_HARDWARE_CONFIG to false in your"
190	              + " RequestOptions and/or in GlideBuilder.setDefaultRequestOptions");
191	    }
192	  }
193	
194	  @Nullable
195	  private synchronized Bitmap getDirtyOrNull(
196	      int width, int height, @Nullable Bitmap.Config config) {
197	    assertNotHardwareConfig(config);
198	    // Config will be null for non public config types, which can lead to transformations naively
199	    // passing in null as the requested config here. See issue #194.
200	    final Bitmap result = strategy.get(width, height, config != null ? config : DEFAULT_CONFIG);
201	    if (result == null) {
202	      if (Log.isLoggable(TAG, Log.DEBUG)) {
203	        Log.d(TAG, "Missing bitmap=" + strategy.logBitmap(width, height, config));
204	      }
205	      misses++;
206	    } else {
207	      hits++;
208	      currentSize -= strategy.getSize(result);
209	      tracker.remove(result);
210	      normalize(result);
211	    }
212	    if (Log.isLoggable(TAG, Log.VERBOSE)) {
213	      Log.v(TAG, "Get bitmap=" + strategy.logBitmap(width, height, config));
214	    }
215	    dump();
216	
217	    return result;
218	  }
219	
220	  // Setting these two values provides Bitmaps that are essentially equivalent to those returned
221	  // from Bitmap.createBitmap.
222	  private static void normalize(Bitmap bitmap) {
223	    bitmap.setHasAlpha(true);
224	    maybeSetPreMultiplied(bitmap);
225	  }
226	
227	  @TargetApi(Build.VERSION_CODES.KITKAT)
228	  private static void maybeSetPreMultiplied(Bitmap bitmap) {
229	    if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.KITKAT) {
230	      bitmap.setPremultiplied(true);
231	    }
232	  }
233	
234	  @Override
235	  public void clearMemory() {
236	    if (Log.isLoggable(TAG, Log.DEBUG)) {
237	      Log.d(TAG, "clearMemory");
238	    }
239	    trimToSize(0);
240	  }
241	
242	  @SuppressWarnings("checkstyle:UnnecessaryParentheses") // Readability
243	  @SuppressLint("InlinedApi")
244	  @Override
245	  public void trimMemory(int level) {
246	    if (Log.isLoggable(TAG, Log.DEBUG)) {
247	      Log.d(TAG, "trimMemory, level=" + level);
248	    }
249	    if (level >= ComponentCallbacks2.TRIM_MEMORY_BACKGROUND
250	        || (Build.VERSION.SDK_INT >= Build.VERSION_CODES.M
251	            && level >= ComponentCallbacks2.TRIM_MEMORY_UI_HIDDEN)) {
252	      clearMemory();
253	    } else if (level >= ComponentCallbacks2.TRIM_MEMORY_UI_HIDDEN
254	        || level == ComponentCallbacks2.TRIM_MEMORY_RUNNING_CRITICAL) {
255	      trimToSize(getMaxSize() / 2);
256	    }
257	  }
258	
259	  private synchronized void trimToSize(long size) {
260	    while (currentSize > size) {
261	      final Bitmap removed = strategy.removeLast();
262	      // TODO: This shouldn't ever happen, see #331.
263	      if (removed == null) {
264	        if (Log.isLoggable(TAG, Log.WARN)) {
265	          Log.w(TAG, "Size mismatch, resetting");
266	          dumpUnchecked();
267	        }
268	        currentSize = 0;
269	        return;
270	      }
271	      tracker.remove(removed);
272	      currentSize -= strategy.getSize(removed);
273	      evictions++;
274	      if (Log.isLoggable(TAG, Log.DEBUG)) {
275	        Log.d(TAG, "Evicting bitmap=" + strategy.logBitmap(removed));
276	      }
277	      dump();
278	      removed.recycle();
279	    }
280	  }
281	
282	  private void dump() {
283	    if (Log.isLoggable(TAG, Log.VERBOSE)) {
284	      dumpUnchecked();
285	    }
286	  }
