288	  private void dumpUnchecked() {
289	    Log.v(
290	        TAG,
291	        "Hits="
292	            + hits
293	            + ", misses="
294	            + misses
295	            + ", puts="
296	            + puts
297	            + ", evictions="
298	            + evictions
299	            + ", currentSize="
300	            + currentSize
301	            + ", maxSize="
302	            + maxSize
303	            + "\nStrategy="
304	            + strategy);
305	  }
