307	  private static LruPoolStrategy getDefaultStrategy() {
308	    final LruPoolStrategy strategy;
309	    if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.KITKAT) {
310	      strategy = new SizeConfigStrategy();
311	    } else {
312	      strategy = new AttributeStrategy();
313	    }
