317	  @TargetApi(Build.VERSION_CODES.O)
318	  private static Set<Bitmap.Config> getDefaultAllowedConfigs() {
319	    Set<Bitmap.Config> configs = new HashSet<>(Arrays.asList(Bitmap.Config.values()));
320	    if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.KITKAT) {
321	      // GIFs, among other types, end up with a native Bitmap config that doesn't map to a java
322	      // config and is treated as null in java code. On KitKat+ these Bitmaps can be reconfigured
323	      // and are suitable for re-use.
