341	    private final Set<Bitmap> bitmaps = Collections.synchronizedSet(new HashSet<Bitmap>());
342	
343	    @Override
344	    public void add(Bitmap bitmap) {
345	      if (bitmaps.contains(bitmap)) {
346	        throw new IllegalStateException(
347	            "Can't add already added bitmap: "
348	                + bitmap
349	                + " ["
350	                + bitmap.getWidth()
351	                + "x"
352	                + bitmap.getHeight()
353	                + "]");
354	      }
355	      bitmaps.add(bitmap);
356	    }
357	
358	    @Override
359	    public void remove(Bitmap bitmap) {
360	      if (!bitmaps.contains(bitmap)) {
361	        throw new IllegalStateException("Cannot remove bitmap not in tracker");
362	      }
363	      bitmaps.remove(bitmap);
364	    }
365	  }
