367	  private static final class NullBitmapTracker implements BitmapTracker {
368	
369	    @Synthetic
370	    NullBitmapTracker() {}
371	
372	    @Override
373	    public void add(Bitmap bitmap) {
374	      // Do nothing.
375	    }
376	
377	    @Override
378	    public void remove(Bitmap bitmap) {
379	      // Do nothing.
