7	/**
8	 * A wrapper resource that allows reference counting a wrapped {@link
9	 * com.bumptech.glide.load.engine.Resource} interface.
10	 *
11	 * @param <Z> The type of data returned by the wrapped {@link Resource}.
12	 */
13	class EngineResource<Z> implements Resource<Z> {
14	  private final boolean isMemoryCacheable;
15	  private final boolean isRecyclable;
16	  private final Resource<Z> resource;
17	  private final ResourceListener listener;
18	  private final Key key;
19	
20	  private int acquired;
21	  private boolean isRecycled;
22	
23	  interface ResourceListener {
24	    void onResourceReleased(Key key, EngineResource<?> resource);
25	  }
26	
27	  EngineResource(
28	      Resource<Z> toWrap,
29	      boolean isMemoryCacheable,
30	      boolean isRecyclable,
31	      Key key,
32	      ResourceListener listener) {
33	    resource = Preconditions.checkNotNull(toWrap);
34	    this.isMemoryCacheable = isMemoryCacheable;
35	    this.isRecyclable = isRecyclable;
36	    this.key = key;
37	    this.listener = Preconditions.checkNotNull(listener);
38	  }
39	
40	  Resource<Z> getResource() {
41	    return resource;
42	  }
43	
44	  boolean isMemoryCacheable() {
45	    return isMemoryCacheable;
46	  }
47	
48	  @NonNull
49	  @Override
50	  public Class<Z> getResourceClass() {
51	    return resource.getResourceClass();
52	  }
53	
54	  @NonNull
55	  @Override
56	  public Z get() {
57	    return resource.get();
58	  }
59	
60	  @Override
61	  public int getSize() {
62	    return resource.getSize();
63	  }
64	
65	  @Override
66	  public synchronized void recycle() {
67	    if (acquired > 0) {
68	      throw new IllegalStateException("Cannot recycle a resource while it is still acquired");
69	    }
70	    if (isRecycled) {
71	      throw new IllegalStateException("Cannot recycle a resource that has already been recycled");
72	    }
73	    isRecycled = true;
74	    if (isRecyclable) {
75	      resource.recycle();
76	    }
77	  }
78	
79	  /**
80	   * Increments the number of consumers using the wrapped resource. Must be called on the main
81	   * thread.
82	   *
83	   * <p>This must be called with a number corresponding to the number of new consumers each time new
84	   * consumers begin using the wrapped resource. It is always safer to call acquire more often than
85	   * necessary. Generally external users should never call this method, the framework will take care
86	   * of this for you.
87	   */
88	  synchronized void acquire() {
89	    if (isRecycled) {
90	      throw new IllegalStateException("Cannot acquire a recycled resource");
91	    }
92	    ++acquired;
93	  }
94	
95	  /**
96	   * Acquires the resource only if at least one other consumer still holds it.
97	   *
98	   * <p>Once the count drops to zero, the releasing thread passes the resource to {@link
99	   * ResourceListener#onResourceReleased}, which moves it into the memory cache. That thread is not
100	   * always the main thread: an {@link EngineJob} drops its own hold on whichever thread finishes
101	   * notifying callbacks. Acquiring the resource in that window would leave an acquired resource in
102	   * the memory cache, and evicting it would then throw from {@link #recycle()}.
103	   *
104	   * @return {@code true} if the resource was acquired, {@code false} if no consumer holds it.
105	   */
106	  synchronized boolean acquireIfInUse() {
107	    if (acquired == 0) {
108	      return false;
109	    }
110	    acquire();
111	    return true;
112	  }
113	
114	  /**
115	   * Decrements the number of consumers using the wrapped resource. Must be called on the main
116	   * thread.
117	   *
118	   * <p>This must only be called when a consumer that called the {@link #acquire()} method is now
119	   * done with the resource. Generally external users should never call this method, the framework
120	   * will take care of this for you.
121	   */
122	  // listener is effectively final.
123	  @SuppressWarnings("SynchronizeOnNonFinalField")
124	  void release() {
125	    boolean release = false;
126	    synchronized (this) {
127	      if (acquired <= 0) {
128	        throw new IllegalStateException("Cannot release a recycled or not yet acquired resource");
129	      }
130	      if (--acquired == 0) {
131	        release = true;
132	      }
133	    }
134	    if (release) {
135	      listener.onResourceReleased(key, this);
136	    }
137	  }
138	
139	  @Override
140	  public synchronized String toString() {
141	    return "EngineResource{"
142	        + "isMemoryCacheable="
143	        + isMemoryCacheable
144	        + ", listener="
145	        + listener
146	        + ", key="
147	        + key
148	        + ", acquired="
149	        + acquired
150	        + ", isRecycled="
151	        + isRecycled
152	        + ", resource="
153	        + resource
154	        + '}';
155	  }
156	}
