143	        + isMemoryCacheable
144	        + ", listener="
145	        + listener
146	        + ", key="
147	        + key
148	        + ", acquired="
149	        + acquired
150	        + ", isRecycled="
151	        + isRecycled
152	        + ", resource="
153	        + resource
154	        + '}';
