92	  public Class<Data> getDataClass() {
93	    return dataClass;
94	  }
95	
96	  @Override
97	  public String toString() {
98	    return "LoadPath{" + "decodePaths=" + Arrays.toString(decodePaths.toArray()) + '}';
99	  }
