346	  private Bitmap decodeFromWrappedStreams(
347	      ImageReader imageReader,
348	      BitmapFactory.Options options,
349	      DownsampleStrategy downsampleStrategy,
350	      DecodeFormat decodeFormat,
351	      PreferredColorSpace preferredColorSpace,
352	      boolean isHardwareConfigAllowed,
353	      int requestedWidth,
354	      int requestedHeight,
355	      boolean fixBitmapToRequestedDimensions,
356	      DecodeCallbacks callbacks)
357	      throws IOException {
358	    long startTime = LogTime.getLogTime();
359	
360	    int[] sourceDimensions = getDimensions(imageReader, options, callbacks, bitmapPool);
361	    int sourceWidth = sourceDimensions[0];
362	    int sourceHeight = sourceDimensions[1];
363	    String sourceMimeType = options.outMimeType;
364	
365	    // If we failed to obtain the image dimensions, we may end up with an incorrectly sized Bitmap,
366	    // so we want to use a mutable Bitmap type. One way this can happen is if the image header is so
367	    // large (10mb+) that our attempt to use inJustDecodeBounds fails and we're forced to decode the
368	    // full size image.
369	    if (sourceWidth == -1 || sourceHeight == -1) {
370	      isHardwareConfigAllowed = false;
371	    }
372	
373	    int orientation = imageReader.getImageOrientation();
374	    int degreesToRotate = TransformationUtils.getExifOrientationDegrees(orientation);
375	    boolean isExifOrientationRequired = TransformationUtils.isExifOrientationRequired(orientation);
376	
377	    int targetWidth =
378	        requestedWidth == Target.SIZE_ORIGINAL
379	            ? (isRotationRequired(degreesToRotate) ? sourceHeight : sourceWidth)
380	            : requestedWidth;
381	    int targetHeight =
382	        requestedHeight == Target.SIZE_ORIGINAL
383	            ? (isRotationRequired(degreesToRotate) ? sourceWidth : sourceHeight)
384	            : requestedHeight;
385	
386	    ImageType imageType = imageReader.getImageType();
387	
388	    calculateScaling(
389	        imageType,
390	        imageReader,
391	        callbacks,
392	        bitmapPool,
393	        downsampleStrategy,
394	        degreesToRotate,
395	        sourceWidth,
396	        sourceHeight,
397	        targetWidth,
398	        targetHeight,
399	        options);

