138	    } catch (IOException e) {
139	      if (Log.isLoggable(TAG, Log.DEBUG)) {
140	        Log.d(TAG, "Failed to get a response code", e);
141	      }
142	    }
143	    return INVALID_STATUS_CODE;
144	  }
