146	  private HttpURLConnection buildAndConfigureConnection(URL url, Map<String, String> headers)
147	      throws HttpException {
148	    HttpURLConnection urlConnection;
149	    try {
150	      urlConnection = connectionFactory.build(url);
151	    } catch (IOException e) {
152	      throw new HttpException("URL.openConnection threw", /* statusCode= */ 0, e);
153	    }
154	    for (Map.Entry<String, String> headerEntry : headers.entrySet()) {
155	      urlConnection.addRequestProperty(headerEntry.getKey(), headerEntry.getValue());
156	    }
157	    urlConnection.setConnectTimeout(timeout);
158	    urlConnection.setReadTimeout(timeout);
159	    urlConnection.setUseCaches(false);
160	    urlConnection.setDoInput(true);
161	    // Stop the urlConnection instance of HttpUrlConnection from following redirects so that
162	    // redirects will be handled by recursive calls to this method, loadDataWithRedirects.
163	    urlConnection.setInstanceFollowRedirects(false);
